import sys,random,json
sys.path.insert(0,'/workspace/project')
import driver
random.seed(333)
names=['A','B','C']
pols=['','match(A) allow;','match(B) allow;','startswith(A) allow;','contains(B) allow;','endswith(A) allow;','not(match(A)) allow;','(startswith(A) and contains(B)) allow;','match(A) drop;','match(A) allow;match(A) drop;','(contains(A) or contains(B)) allow;','match(X) allow;','bad','match(A) allow']
opfields={
 'stage':{'epoch':lambda:random.randint(1,10),'policy':lambda:random.choice(pols)},
 'commit':{'epoch':lambda:random.randint(1,10)},
 'retire':{'epoch':lambda:random.randint(1,10)},
 'spawn':{'unit':lambda:[random.randint(0,2),random.randint(1,5),random.randint(1,5)],'service':lambda:random.choice(names+['X'])},
 'clone':{'parent':lambda:[random.randint(0,2),random.randint(1,5),random.randint(1,5)],'child':lambda:[random.randint(0,2),random.randint(1,5),random.randint(1,5)]},
 'exit':{'unit':lambda:[random.randint(0,2),random.randint(1,5),random.randint(1,5)]},
 'begin':{'unit':lambda:[random.randint(0,2),random.randint(1,5),random.randint(1,5)],'rid':lambda:random.randint(1,8)},
 'finish':{'unit':lambda:[random.randint(0,2),random.randint(1,5),random.randint(1,5)],'rid':lambda:random.randint(1,8)},
 'open':{'connection':lambda:[random.randint(1,3),random.randint(1,5)]},
 'close':{'connection':lambda:[random.randint(1,3),random.randint(1,5)]},
 'send':{'unit':lambda:[random.randint(0,2),random.randint(1,5),random.randint(1,5)],'rid':lambda:random.randint(1,8),'connection':lambda:[random.randint(1,3),random.randint(1,5)],'stream':lambda:random.randint(1,8),'destination':lambda:random.choice(names+['X'])},
 'recv':{'connection':lambda:[random.randint(1,3),random.randint(1,5)],'stream':lambda:random.randint(1,8),'unit':lambda:[random.randint(0,2),random.randint(1,5),random.randint(1,5)],'rid':lambda:random.randint(1,8),'wire':lambda:random.choice([None,'0'*48,'A'*48,'x'])},
 'store':{'unit':lambda:[random.randint(0,2),random.randint(1,5),random.randint(1,5)],'rid':lambda:random.randint(1,8),'file':lambda:[random.randint(1,3),random.randint(1,5)]},
 'load':{'file':lambda:[random.randint(1,3),random.randint(1,5)],'unit':lambda:[random.randint(0,2),random.randint(1,5),random.randint(1,5)],'rid':lambda:random.randint(1,8)},
 'unlink':{'file':lambda:[random.randint(1,3),random.randint(1,5)]},
 'inspect':{}
}
lims={'images':4,'cells':100,'units':4,'contexts':10,'connections':3,'packets':6,'files':3}
def mkjob(valid):
 services=[{'name':n,'label':i+1} for i,n in enumerate(names)]
 limits=dict(lims)
 events=[]
 for _ in range(random.randint(0,200)):
  op=random.choice(list(opfields))
  e={'op':op}
  for k,f in opfields[op].items():e[k]=f()
  events.append(e)
 job={'services':services,'limits':limits,'events':events}
 if not valid:
  k=random.choice(['services','limits','events','extra'])
  if k=='services':job['services']=[]
  elif k=='limits':job['limits']={'x':1}
  elif k=='events':job['events']={}
  else:job['extra']=1
 return job
for trial in range(500):
 jobs=[mkjob(random.random()<.75) for _ in range(random.randint(0,4))]
 data=json.dumps({'jobs':jobs},separators=(',',':')).encode()
 r=driver.solve(data)
 if 'error' in r:
  continue
 assert len(r['results'])==len(jobs)
 for job,res in zip(jobs,r['results']):
  if 'error' in res:
   assert res=={'error':'invalid'}
  else:
   assert len(res['events'])==len(job['events']), (len(res['events']),len(job['events']))
print('driver fuzz structure ok')
